const qs = [
  "CreateMemo|ListMemos|DeleteMemo|SignIn|Transcribe|ShortcutService|service .*Service",
  "type .*Store|interface .*Store|GetUser|CreateMemo",
  "New.*Client|create.*Client|MemoServiceClient|memo.*mutation|listMemos",
  "Webhook|webhook|SSE|EventSource|sse|Broadcast|Run.*Worker|scheduler|runner",
  "CREATE TABLE|CREATE TABLE IF NOT EXISTS"
];
const rs = await Promise.all(qs.map(q => tools.exec_command({cmd:`rg -n -i '${q}' proto server store web cmd internal 2>/dev/null | head -160`,workdir:"/bench/repo",yield_time_ms:10000,max_output_tokens:10000})));
rs.forEach((r,i)=>{ text(`---${i}---\n${r.output}`); });

