const cmds=[
"rg --files web/src | rg 'memo|Memo|query|mutation|connect'",
"rg -n 'useQuery|useMutation|listMemos|createMemo|updateMemo|deleteMemo' web/src --glob '*.ts' --glob '*.tsx' | head -180",
"nl -ba server/router/api/v1/v1.go | sed -n '60,155p'",
"nl -ba server/router/api/v1/memo_service_filter.go | sed -n '1,240p'",
"nl -ba store/db/sqlite/memo.go | sed -n '1,90p'; nl -ba store/db/postgres/memo.go | sed -n '1,75p'",
"nl -ba server/router/api/v1/memo_service_webhooks.go | sed -n '1,130p'; nl -ba internal/webhook/webhook.go | sed -n '120,180p'",
"nl -ba server/runner/s3presign/runner.go | sed -n '1,100p'; nl -ba server/runner/memopayload/runner.go | sed -n '1,90p'"
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:"/bench/repo",yield_time_ms:10000,max_output_tokens:10000})));
rs.forEach((r,i)=>text(`---${i+1}---\n${r.output}`));

